import unittest
from program import run

class T(unittest.TestCase):
    def test_case_00(self):
        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'lo': 0, 'hi': 3, 'flags': ['hi', 'n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'lo': 0, 'hi': 3, 'flags': ['hi', 'n']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'lo': 0, 'hi': 3, 'flags': ['hi', 'n']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'lo': 0, 'hi': 0, 'flags': []})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'lo': 0, 'hi': 3, 'flags': ['hi', 'n']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'lo': 1, 'hi': 0, 'flags': ['lo', 'n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'lo': 0, 'hi': 4, 'flags': ['hi', 'n']})
